#!/bin/bash
# ============================================================
# run_regenie_full_phase3.sh — wait for MR exposure files to be ready, then automatically run MR + full pipeline comparison
#
# Trigger: mr_regenie/apag_exposure_for_mr.csv.gz and apag_sig_snps_for_mr.csv both exist
#   (generated by 4_2_prepare_mr_exposure.py in Phase 2)
#
# Steps:
#   1. 4_3_run_mr_analysis.R --outcome ieu-a-23   (exposure = regenie full sample)
#   2. 4_3_run_mr_analysis.R --outcome finn-b-T2D
#   3. 3_6_compare_regenie_plink.py  (PLINK vs REGENIE full pipeline comparison)
#
# Note: MR requires OpenGWAS network access; failures are only logged and do not stop the subsequent comparison.
#
# Usage: bash code/03_genetics/run_regenie_full_phase3.sh &
# ============================================================
# ── paths (override via env: PANCREASAGE_DATA / PANCREASAGE_OUT / PLINK2 / REGENIE) ──
PKG_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
DATA_ROOT="${PANCREASAGE_DATA:-${PKG_ROOT}/data}"
OUT_ROOT="${PANCREASAGE_OUT:-${PKG_ROOT}/results}"
set -u
RES="${RES:-${OUT_ROOT}}"
LOG="$RES/logs_regenie/phase3_full.log"
EXPOSURE="$RES/mr_regenie/apag_exposure_for_mr.csv.gz"
SIGFILE="$RES/mr_regenie/apag_sig_snps_for_mr.csv"
mkdir -p "$RES/logs_regenie" "$RES/mr_regenie"
cd "${PKG_ROOT}" || exit 1

echo "[$(date)] Phase3 watcher started" > "$LOG"
while :; do
    if [ -f "$EXPOSURE" ] && [ -f "$SIGFILE" ]; then
        break
    fi
    echo "[$(date)] waiting for MR exposure (mr_regenie/)" >> "$LOG"
    sleep 300
done

echo "[$(date)] exposure ready, running MR (regenie full)" >> "$LOG"
for OC in ieu-a-23 finn-b-T2D; do
    echo "[$(date)] MR outcome: $OC" >> "$LOG"
    Rscript code/03_genetics/4_3_run_mr_analysis.R --outcome "$OC" \
        --exposure "$EXPOSURE" --out-root "$RES/mr_regenie" >> "$LOG" 2>&1
    echo "[$(date)] MR $OC exit=$?" >> "$LOG"
done

echo "[$(date)] running full PLINK vs REGENIE comparison" >> "$LOG"
python code/03_genetics/3_6_compare_regenie_plink.py >> "$LOG" 2>&1
echo "[$(date)] Phase 3 done" >> "$LOG"
